def serialize_instance_to_base64_json(instance, cls):
    serialized_attrs = {}
    for attr_name in dir(cls):
        if attr_name.startswith('public_'):
            try:
                attr_value = getattr(instance, attr_name)
            except AttributeError:
                continue
            if isinstance(attr_value, (int, float, str, bool, list, dict)):
                serialized_attrs[attr_name] = attr_value
    json_string = json.dumps(serialized_attrs)
    base64_string = base64.b64encode(json_string.encode('utf-8'))
    return base64_string.decode('utf-8')
```

